text:
{
  "characters": [
    {
      "id": "mina",
      "want": "毎朝つける温度の数字が、自分の手で正しく書かれたままでいてほしい。",
      "need": "数字が誰かの都合で書き換えられても、自分が測った事実を自分の言葉で持ちこたえること。",
      "fear": "自分の帳面が、町の記録の書き換えに加担していたと後から分かること。",
      "wound": "父が死んだ日、帳面の最後の頁に日付だけを書いたまま何も残さなかったこと。",
      "secret": "三年前から、掲示する数字を組合に合わせて一度だけ丸めて書いた。",
      "principle": "測った値は、誰に聞かれても同じことを言う。",
      "self_view": "自分は湯守ではなく、測るだけの人間だと思っている。",
      "others_view": [
        "源治から見れば、宗一の娘ではなく、まだ帳面を閉じ方を知らない若い配湯係。",
        "ユウジから見れば、扱いやすい真面目な職員。数字さえ合っていれば文句を言わない。"
      ],
      "predictions": [
        {"situation": "掲示する数字と帳面の数字が食い違ったとき", "choice": "掲示を直すのではなく、帳面の余白に測り直した時刻を書き足す。"},
        {"situation": "源治が湯口の話を濁したとき", "choice": "問い詰めず、翌朝もう一度同じ質問をする。"},
        {"situation": "掘削の書類に自分の署名を求められたとき", "choice": "署名を保留し、父の帳面を先に読み返す。"}
      ],
      "speech": {
        "sample": "六時四十分、一号湯、四十二度二分。二号湯は四十一度八分。……昨日より三分低いです。",
        "vocab": ["測る", "帳面", "時刻", "三分", "書き足す"],
        "avoid": ["運命", "奇跡", "きっと大丈夫", "感動"]
      },
      "arc": {
        "endpoint": "誰かの正しさのために数字を丸めるのをやめ、下がる湯を下がるまま書く側に残る。",
        "changed": ["食い違った数字を丸めて書くこと", "父の空白を埋めてもらおうとすること"],
        "unchanged": ["毎朝同じ時刻に測ること", "聞かれたことに同じ答えを返すこと"]
      },
      "bans": ["感情を涙で示す", "年長者を説教で論破する", "数字を勘で決める"]
    },
    {
      "id": "genji",
      "want": "十五年前に自分がやったことを、町の誰にも思い出させないまま冬を越すこと。",
      "need": "塞いだ理由を、裁かれない形で一度だけ誰かに話すこと。",
      "fear": "あの夜の作業が、若い配湯係の数字ひとつで暴かれること。",
      "wound": "塞いだ湯口の漆喰が固まる前に、宗一が倒れたこと。",
      "secret": "封鎖を決めたのは古老会ではなく、自分と宗一の二人だった。",
      "principle": "湯の話は、湯屋の中でだけする。",
      "self_view": "自分は町の湯を守ったのであって、隠したのではない。",
      "others_view": [
        "ミナから見れば、何でも知っていて何も言わない老人。",
        "ユウジから見れば、書類に判を押さないだけの障碍。"
      ],
      "predictions": [
        {"situation": "ミナが奥湯の湯口の話を出したとき", "choice": "話を逸らし、代わりに手の火傷の手当てを頼む。"},
        {"situation": "組合が掘削の押印を求めてきたとき", "choice": "判を押さず、代わりに自分の名で異議の書面を一通だけ書く。"},
        {"situation": "ミナが父の帳面を持ってきたとき", "choice": "読まずに、宗一が最後にいた場所を口にする。"}
      ],
      "speech": {
        "sample": "その湯口はな、もう湯が通っとらんのや。掘っても戻らんよ。……手、ちょっと貸してくれ。",
        "vocab": ["湯口", "湯が通る", "あの夜", "手", "戻らん"],
        "avoid": ["謝罪の長広舌", "若者への説教", "感情の説明"]
      },
      "arc": {
        "endpoint": "隠した理由を一通の書面に書き、裁かれることを選ぶ。",
        "changed": ["湯口の話を濁すこと", "一人で背負うこと"],
        "unchanged": ["湯屋の中でしか湯の話をしないこと", "判を安易に押さないこと"]
      },
      "bans": ["自分から長く語り出す", "若い女性を抱きしめる", "泣いて許しを乞う"]
    },
    {
      "id": "yuji",
      "want": "今冬の客を落とさず、掘削許可を年度内に通すこと。",
      "need": "自分の仕事が町に何をもたらすかを、数字の外側でも説明できるようになること。",
      "fear": "温度の低下が表に出て、宿の予約が一斉に流れること。",
      "wound": "前の職場で、隠した数字が原因で同僚が一人辞めたこと。",
      "secret": "年報の温度欄を、自分の判断で上書きの紙で覆った。",
      "principle": "書類は、町が生き延びる順序に並べる。",
      "self_view": "自分は町の暮らしを数字で守っている実務家だと思っている。",
      "others_view": [
        "ミナから見れば、数字を丸めることを悪びれない人。",
        "源治から見れば、湯を知らないまま湯を売ろうとしている若造。"
      ],
      "predictions": [
        {"situation": "ミナが掲示と帳面の食い違いを指摘したとき", "choice": "謝らずに、掲示の書式を変える提案として受け取る。"},
        {"situation": "掘削の申請が止まりかけたとき", "choice": "止めた相手を責めず、条件を一つ譲る。"},
        {"situation": "源治が異議の書面を出したとき", "choice": "握り潰さず、町会に回して自分の名前で説明する。"}
      ],
      "speech": {
        "sample": "掲示の数字を下げるのは、別に隠すためじゃないんです。冬の予約が入ってるんですよ、三月まで。",
        "vocab": ["予約", "年度内", "書式", "説明", "町会"],
        "avoid": ["悪役の嘲笑", "湯を守る者への侮辱", "開き直り"]
      },
      "arc": {
        "endpoint": "隠した数字を自分から町会に出し、その上で掘削の条件を引き受ける。",
        "changed": ["上書きで数字を覆うこと", "書類だけで町を説得しようとすること"],
        "unchanged": ["冬の客を落とさないこと", "仕事の順序を自分で決めること"]
      },
      "bans": ["私利私欲の悪役として振る舞う", "ミナを脅す", "湯を故意に止める"]
    },
    {
      "id": "soichi",
      "want": "最後まで湯守の帳面を、誰にも渡さずに閉じること。",
      "need": "自分がやったことを、娘に責任としてではなく手順として残すこと。",
      "fear": "塞いだ湯口の理由が、自分の死と一緒に消えること。",
      "wound": "源治と二人で漆喰を詰めた夜、途中で手が止まったこと。",
      "secret": "封鎖の判断を、源治より先に自分が口にした。",
      "principle": "帳面に書かないことは、無かったことと同じになる。",
      "self_view": "自分は最後まで湯守だったと思っている。",
      "others_view": [
        "ミナから見れば、日付だけ書いて黙った父。",
        "源治から見れば、先に倒れた相棒。"
      ],
      "predictions": [
        {"situation": "封鎖の翌朝、源治が記入をためらったとき", "choice": "自分が先に帳面を開き、日付だけを書く。"},
        {"situation": "組合から説明を求められたとき", "choice": "崩落として書類を通す。名は書かない。"},
        {"situation": "ミナに帳面を渡す段になったとき", "choice": "頁を閉じ、手順だけを口で伝えようとする。"}
      ],
      "speech": {
        "sample": "日付は書いた。理由は書かん。……お前が書く頁は、お前の字で埋めなさい。",
        "vocab": ["帳面", "日付", "頁", "手順", "字"],
        "avoid": ["現在の場面での発話", "未来の出来事への言及"]
      },
      "arc": {
        "endpoint": "十五年前に既に終わっている。以後、行為者にも発話者にもならない。",
        "changed": ["なし（物語の現在では既に死んでいる）"],
        "unchanged": ["帳面の最後の頁を白紙のまま残したこと"]
      },
      "bans": ["現在の場面に登場する", "回想以外で発言する", "ミナに直接語りかける"]
    }
  ]
}
